arguments.feature_code:
import numpy as np
for col in ['x4', 'x6', 'x7']:
    if col in df.columns:
        # Shift to positive range before log1p
        min_val = df[col].min()
        if min_val < 0:
            df[f'{col}_log1p'] = np.log1p(df[col] - min_val)
        else:
            df[f'{col}_log1p'] = np.log1p(df[col])

