import numpy as np

# Ensure x5 is imputed if present
if 'x5' in df.columns:
    if is_fit:
        valid_x5 = df.loc[df['x5'] != 999.0, 'x5']
        state['x5_median_iter3'] = valid_x5.median() if len(valid_x5) > 0 else 0.0
    df['x5'] = df['x5'].replace(999.0, state.get('x5_median_iter3', 0.0))

# Interactions between top predictors
if 'x4' in df.columns and 'x5' in df.columns:
    df['x4_mul_x5'] = df['x4'] * df['x5']
if 'x4' in df.columns and 'x9' in df.columns:
    df['x4_mul_x9'] = df['x4'] * df['x9']
if 'x5' in df.columns and 'x9' in df.columns:
    df['x5_mul_x9'] = df['x5'] * df['x9']

# Interactions for secondary predictors
if 'x1' in df.columns and 'x2' in df.columns:
    df['x1_mul_x2'] = df['x1'] * df['x2']
if 'x1' in df.columns and 'x8' in df.columns:
    df['x1_mul_x8'] = df['x1'] * df['x8']
if 'x2' in df.columns and 'x8' in df.columns:
    df['x2_mul_x8'] = df['x2'] * df['x8']

# Log transforms for skewed positive features
for col in ['x5', 'x10', 'x11']:
    if col in df.columns:
        df[f'{col}_log'] = np.log1p(df[col].clip(0))

