for col in ['x6', 'x7', 'x10', 'x11']:
    c_min = state['scaler_params'][col]['min']
    c_max = state['scaler_params'][col]['max']
    # Add epsilon to denominator to prevent division by zero if min == max
    df[f'{col}_minmax'] = (df[col] - c_min) / (c_max - c_min + 1e-7)

